import 'server-only'

export async function logPageView(path: string): Promise<void> {
  const endpoint = process.env.ANALYTICS_URL
  if (!endpoint) {
    console.warn('Page view not logged: ANALYTICS_URL is not configured')
    return
  }

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ event: 'page_view', path, timestamp: new Date().toISOString() }),
    cache: 'no-store',
  })

  if (!response.ok) {
    throw new Error(`Page view logging failed: ${response.status}`)
  }
}

